import { readFile, mkdir, writeFile } from "node:fs/promises";
import ts from "typescript";
const source = await readFile("src/lib/assisted-apply.ts", "utf8");
const built = ts.transpileModule(source, {
  compilerOptions: {
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ES2022,
    removeComments: false,
  },
}).outputText;
await mkdir("browser-extension/generated", { recursive: true });
await writeFile(
  "browser-extension/generated/policy.js",
  "// Generated by npm run extension:build. Edit src/lib/assisted-apply.ts.\n" +
    built,
);
